leep?"}]}]}, {"kind": "matrix", "id": "supp_block_11", "title": "Sleep, Sexual Function, and Overall", "instructions": "", "options": [{"value": 5, "label": "Not at all"}, {"value": 4, "label": "A little bit"}, {"value": 3, "label": "Somewhat"}, {"value": 2, "label": "Quite a bit"}, {"value": 1, "label": "Very much"}, {"value": 0, "label": "Prefer not to answer"}], "sections": [{"header": "Sleep, Sexual Function, and Overall", "items": [{"id": "SUP-83", "text": "In the past 30 days, how much has your condition interfered with your sexual activity?"}]}]}, {"kind": "nrs", "id": "Global07", "prompt": "In the past 7 days, how would you rate your pain on average?", "minLabel": "No pain", "maxLabel": "Worst pain imaginable"}]}}'::jsonb, '{"type": "none"}'::jsonb
where not exists (select 1 from public.instruments where scoring_config_key = 'adl_supplemental');

