  values ('promis_pf_sf20a', 'PFA16r1', 1, 'Are you able to dress yourself, including tying shoelaces and buttoning your clothes?', '[{"value": 5, "label": "Without any difficulty"}, {"value": 4, "label": "With a little difficulty"}, {"value": 3, "label": "With some difficulty"}, {"value": 2, "label": "With much difficulty"}, {"value": 1, "label": "Unable to do"}]'::jsonb, false, 'Dressing', 'Upper extremity, Lower extremity, Cervical spine, Thoracic spine, Lumbar spine', '5-point Likert (difficulty)', 'Scored on PF 20a. | Scores: promis_pf_sf20a')
