-- 3. Battery (one per organization) ---------------------------------------
insert into public.batteries (organization_id, name, instrument_ids, is_active)
select o.id, 'ADL Functional Assessment (PROMIS PF 20a · UE 7a · Neuro-QOL UE)', array[
      (select id from public.instruments where scoring_config_key = 'promis_pf_sf20a'),
      (select id from public.instruments where scoring_config_key = 'promis_ue_sf7a'),
      (select id from public.instruments where scoring_config_key = 'neuroqol_ue_sf'),
      (select id from public.instruments where scoring_config_key = 'adl_supplemental')
    ]::uuid[], true
  from public.organizations o
 where not exists (
   select 1 from public.batteries b
    where b.organization_id = o.id and b.name = 'ADL Functional Assessment (PROMIS PF 20a · UE 7a · Neuro-QOL UE)'
 );
